ALTER TABLE public.workspace_members ADD COLUMN IF NOT EXISTS record_permissions jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE public.workspace_members ADD COLUMN IF NOT EXISTS can_manage_trips boolean NOT NULL DEFAULT false;
CREATE TABLE public.workspace_record_shares (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.workspaces(id), record_kind text NOT NULL CHECK(record_kind IN ('vehicles','drivers','contacts','payers')), record_id uuid NOT NULL, user_id uuid NOT NULL, access_level text NOT NULL DEFAULT 'read' CHECK(access_level IN ('read','manage')), created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(record_kind,record_id,user_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.workspace_record_shares TO authenticated;
GRANT ALL ON public.workspace_record_shares TO service_role;
ALTER TABLE public.workspace_record_shares ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.business_record_access(_ws uuid,_kind text,_id uuid,_level text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.workspace_members m JOIN public.workspaces w ON w.id=m.workspace_id JOIN public.user_profiles p ON p.user_id=m.user_id WHERE m.workspace_id=_ws AND m.user_id=auth.uid() AND w.status='active' AND p.status='active' AND (CASE WHEN m.is_contractor THEN EXISTS(SELECT 1 FROM public.workspace_record_shares s WHERE s.workspace_id=_ws AND s.record_kind=_kind AND s.record_id=_id AND s.user_id=auth.uid() AND (_level='read' OR s.access_level='manage')) ELSE m.role IN ('owner','admin') OR m.record_permissions->>_kind='manage' OR (_level='read' AND m.record_permissions->>_kind='read') OR EXISTS(SELECT 1 FROM public.workspace_record_shares s WHERE s.workspace_id=_ws AND s.record_kind=_kind AND s.record_id=_id AND s.user_id=auth.uid() AND (_level='read' OR s.access_level='manage')) END)) $$;
REVOKE ALL ON FUNCTION public.business_record_access(uuid,text,uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.business_record_access(uuid,text,uuid,text) TO authenticated,service_role;
CREATE POLICY record_shares_read ON public.workspace_record_shares FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.workspace_role_of(workspace_id,auth.uid()) IN ('owner','admin'));
CREATE POLICY record_shares_manage ON public.workspace_record_shares FOR ALL TO authenticated USING(public.workspace_role_of(workspace_id,auth.uid()) IN ('owner','admin')) WITH CHECK(public.workspace_role_of(workspace_id,auth.uid()) IN ('owner','admin') AND created_by=auth.uid());
CREATE OR REPLACE FUNCTION public.stamp_owner_workspace() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _owner uuid; _ws uuid; BEGIN IF TG_TABLE_NAME='payers' THEN _owner:=NEW.owner_user_id; ELSE _owner:=NEW.owner_id; END IF; IF TG_OP='UPDATE' THEN NEW.workspace_id:=OLD.workspace_id; NEW.created_by:=coalesce(OLD.created_by,_owner); NEW.creator_mfn_id:=coalesce(OLD.creator_mfn_id,(SELECT mfn_id FROM public.user_profiles WHERE user_id=NEW.created_by)); IF TG_TABLE_NAME='payers' THEN NEW.owner_user_id:=OLD.owner_user_id; ELSE NEW.owner_id:=OLD.owner_id; END IF; ELSE NEW.created_by:=coalesce(auth.uid(),_owner); SELECT mfn_id INTO NEW.creator_mfn_id FROM public.user_profiles WHERE user_id=NEW.created_by; NEW.workspace_id:=NULL; END IF; IF NEW.workspace_id IS NULL THEN SELECT CASE WHEN count(*)=1 THEN min(m.workspace_id::text)::uuid END INTO _ws FROM public.workspace_members m JOIN public.workspaces w ON w.id=m.workspace_id WHERE m.user_id=_owner AND w.status='active'; NEW.workspace_id:=_ws; END IF; RETURN NEW; END $$;
DO $$ DECLARE t text; k text; o text; p record; BEGIN FOREACH t IN ARRAY ARRAY['vehicles','drivers','provider_contacts','payers'] LOOP k:=CASE WHEN t='provider_contacts' THEN 'contacts' ELSE t END; o:=CASE WHEN t='payers' THEN 'owner_user_id' ELSE 'owner_id' END; EXECUTE format('ALTER TABLE public.%I ADD COLUMN IF NOT EXISTS created_by uuid, ADD COLUMN IF NOT EXISTS creator_mfn_id text',t); EXECUTE format('UPDATE public.%I r SET created_by=r.%I, creator_mfn_id=(SELECT mfn_id FROM public.user_profiles WHERE user_id=r.%I) WHERE r.created_by IS NULL',t,o,o); EXECUTE format('UPDATE public.%I r SET workspace_id=q.ws FROM (SELECT m.user_id,min(m.workspace_id::text)::uuid ws FROM public.workspace_members m JOIN public.workspaces w ON w.id=m.workspace_id WHERE w.status=''active'' GROUP BY m.user_id HAVING count(*)=1) q WHERE r.%I=q.user_id AND r.workspace_id IS NULL',t,o); FOR p IN SELECT policyname FROM pg_policies WHERE schemaname='public' AND tablename=t LOOP EXECUTE format('DROP POLICY %I ON public.%I',p.policyname,t); END LOOP; EXECUTE format('CREATE POLICY business_read ON public.%I FOR SELECT TO authenticated USING(public.business_record_access(workspace_id,%L,id,''read''))',t,k); EXECUTE format('CREATE POLICY business_insert ON public.%I FOR INSERT TO authenticated WITH CHECK(public.business_record_access(workspace_id,%L,id,''manage'') AND created_by=auth.uid())',t,k); EXECUTE format('CREATE POLICY business_update ON public.%I FOR UPDATE TO authenticated USING(public.business_record_access(workspace_id,%L,id,''manage'')) WITH CHECK(public.business_record_access(workspace_id,%L,id,''manage''))',t,k,k); EXECUTE format('CREATE POLICY business_delete ON public.%I FOR DELETE TO authenticated USING(public.business_record_access(workspace_id,%L,id,''manage''))',t,k); END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.guard_business_permissions() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF (NEW.record_permissions IS DISTINCT FROM OLD.record_permissions OR NEW.can_manage_trips IS DISTINCT FROM OLD.can_manage_trips) AND auth.uid() IS NOT NULL AND NOT public.is_master_admin(auth.uid()) AND coalesce(public.workspace_role_of(OLD.workspace_id,auth.uid())::text,'') NOT IN ('owner','admin') THEN RAISE EXCEPTION 'Only account owners and admins may grant permissions'; END IF; IF NEW.is_contractor AND (NEW.record_permissions<>'{}'::jsonb OR NEW.can_manage_trips) THEN RAISE EXCEPTION 'Contractors require record-specific assignments'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_business_permissions BEFORE UPDATE ON public.workspace_members FOR EACH ROW EXECUTE FUNCTION public.guard_business_permissions();
COMMENT ON COLUMN public.workspace_members.record_permissions IS 'Explicit workspace resource access by vehicles/drivers/contacts/payers; read/manage only. Contractors require record-specific shares.';